import {roundedPomodoros, elapsedSeconds, settleTimer, startTask, getTodoSections} from './core.mjs';
const $ = (s) => document.querySelector(s);
const icons={todo:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 9 1 1 2-2m3 1h3m-9 6 1 1 2-2m3 1h3"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l3 3h6a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h1m6 0h1"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="currentColor"/><circle cx="15" cy="12" r="2" fill="currentColor"/><circle cx="8" cy="18" r="2" fill="currentColor"/>',play:'<path d="m8 5 11 7-11 7Z" fill="currentColor" stroke="none"/>',pause:'<path d="M8 5v14m8-14v14" stroke-width="3"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2" fill="currentColor" stroke="none"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',leaf:'<path d="M20 3C8 2 2 9 5 16s15 5 15-13ZM4 21 16 9"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',book:'<path d="M12 5C9 3 5 3 3 4v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',cup:'<path d="M5 6h12v9a5 5 0 0 1-10 0V6m10 2h2a3 3 0 0 1 0 6h-2M3 22h18M9 1v2m5-2v2"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.folder}</svg>`;
const escape=(text)=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const today=()=>localDate();
const offsetDate=(offset,base=today())=>{const d=new Date(base+'T12:00:00');d.setDate(d.getDate()+offset);return localDate(d)};
const dateLabel=(date)=>new Date(date+'T12:00:00').toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'});
const uid=()=>crypto.randomUUID();
const seed=()=>({version:1,settings:{focus:1500,rest:300},projects:[{id:'p1',name:'사이드 프로젝트',icon:'folder',color:'#d08c6f'},{id:'p2',name:'디자인 학습',icon:'book',color:'#84956c'},{id:'p3',name:'독서',icon:'leaf',color:'#b49b65'}],tasks:[{id:'t1',title:'프로젝트 아이디어 정리',estimate:2,project:'p1',date:today(),done:false},{id:'t2',title:'디자인 강의 수강',estimate:2,project:'p2',date:today(),done:false},{id:'t3',title:'도서 읽기',estimate:1,project:'p3',date:today(),done:false},{id:'t4',title:'첫 화면 참고 자료 조사',estimate:2,project:'p1',date:offsetDate(1),done:false},{id:'t5',title:'주간 할 일 정리',estimate:1,project:'',date:'',done:false}],records:[],timer:null});
let state=seed(),storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem('to3mato-demo-v1'));if(saved?.version===1&&Array.isArray(saved.tasks)&&Array.isArray(saved.records)&&Array.isArray(saved.projects)&&saved.settings?.focus>0)state=saved;}catch{}
let tab='todo',projectView=null,selectedDate=today(),weekOffset=0,editId=null,toastHandle;
const save=()=>{try{localStorage.setItem('to3mato-demo-v1',JSON.stringify(state));}catch{storageAvailable=false;notify('저장할 수 없습니다. 브라우저 저장 공간을 확인하세요.');}};
const notify=(msg)=>{$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastHandle);toastHandle=setTimeout(()=>$('#toast').classList.remove('visible'),3300)};
const taskTotal=(id)=>state.records.filter(r=>r.taskId===id).reduce((s,r)=>s+r.pomodoros,0);
const tomato=(filled=false)=>`<svg class="mini-tomato ${filled?'filled':''}" viewBox="0 0 24 24" aria-hidden="true"><path class="body" d="M12 7C7 4.5 2 8 2.5 13.5 3 18.5 7 22 12 22s9-3.5 9.5-8.5C22 8 17 4.5 12 7Z"/><path class="calyx" d="m12 8.5-4.4-.4 2-2-2.8-1.2 3-.4.4-2.2L12 4l1.8-1.7.4 2.2 3 .4-2.8 1.2 2 2Z"/></svg>`;
const pomos=(estimate,actual=0)=>`<span class="tomatoes" aria-label="예상 ${estimate}포모도로 / 기록 ${actual}포모도로">${Array.from({length:Math.min(6,estimate)},(_,i)=>tomato(i<Math.floor(actual))).join('')}<span class="pomo-label">${actual} / ${estimate}</span></span>`;
const addButton=(label='할 일 추가')=>`<button class="add-task" data-action="add">${icon('plus')}${label}</button>`;
function taskRow(t){const project=state.projects.find(p=>p.id===t.project);const date=t.date===today()?'오늘':t.date?dateLabel(t.date).split(' ').slice(0,2).join(' '):'날짜 미지정';return `<article class="task-row ${t.done?'done':''} ${state.timer?.taskId===t.id&&state.timer?.phase==='focus'?'current':''}" draggable="true" data-task="${t.id}"><button class="check ${t.done?'checked':''}" data-action="complete" data-id="${t.id}" aria-label="${escape(t.title)} ${t.done?'완료 취소':'완료'}">${t.done?icon('check'):''}</button><button class="task-detail" data-action="edit" data-id="${t.id}"><span class="task-title">${escape(t.title)}</span><span class="task-meta">${project?`<span><i class="project-dot" style="background:${project.color}"></i>${escape(project.name)}</span>`:'<span>프로젝트 없음</span>'}<span>·</span><span>${date}</span></span></button>${pomos(t.estimate,taskTotal(t.id))}<button class="task-more" data-action="edit" data-id="${t.id}" aria-label="${escape(t.title)} 수정">${icon('more')}</button></article>`}
const list=(tasks)=>`<div class="task-list">${tasks.length?tasks.map(taskRow).join(''):'<div class="empty">등록된 할 일이 없습니다.</div>'}</div>`;
function renderNav(){const tabs=[['todo','할 일','todo'],['projects','프로젝트','folder'],['calendar','캘린더','calendar'],['settings','설정','settings']];$('.tabs').innerHTML=tabs.map(([id,name,i])=>`<button class="tab ${tab===id?'active':''}" data-tab="${id}" aria-current="${tab===id?'page':'false'}">${icon(i)}${name}</button>`).join('');$('#date-label').textContent=new Date().toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'short'});}
function renderWorkspace(){renderNav();let html='';if(tab==='todo'){
 const sections=getTodoSections(state.tasks,today());
 html='<div class="todo-sections">'+sections.map(section=>`<section class="todo-section" data-date="${section.date}" aria-label="${escape(section.label)}"><div class="todo-section-heading"><h2>${escape(section.label)}</h2><span class="section-task-count">${section.tasks.length}</span></div>${section.tasks.length?list(section.tasks):''}<button class="section-add" data-action="add" data-add-date="${section.date}" aria-label="${escape(section.label)} 할 일 추가">${icon('plus')}할 일 추가</button></section>`).join('')+'</div>';
 }else if(tab==='projects'){
 if(projectView){const project=state.projects.find(p=>p.id===projectView);html=`<button class="back-button" data-action="project-back">${icon('back')}모든 프로젝트</button><div class="intro"><div><h1>${escape(project.name)}</h1></div></div>${list(state.tasks.filter(t=>t.project===projectView))}${addButton('할 일 추가')}`;}else{html=`<div class="project-grid">${state.projects.map(p=>{const tasks=state.tasks.filter(t=>t.project===p.id),done=tasks.filter(t=>t.done).length;return `<button class="project-card" data-project="${p.id}"><span class="project-symbol" style="color:${p.color}">${icon(p.icon)}</span><h2>${escape(p.name)}</h2><div class="project-bottom"><span>${tasks.length}개의 할 일 · ${done}개 완료</span><span class="pomo-count">${tasks.reduce((s,t)=>s+t.estimate,0)}${tomato(true)}</span></div><div class="progress-line"><div style="width:${tasks.length?done/tasks.length*100:0}%"></div></div></button>`}).join('')}</div><button class="add-task" data-action="add-project">${icon('plus')}프로젝트 추가</button>`;}
 }else if(tab==='calendar'){
 const d=new Date(today()+'T12:00:00'),mon=offsetDate(-((d.getDay()+6)%7)+weekOffset*7);const dates=Array.from({length:7},(_,i)=>offsetDate(i,mon));
 html=`<div class="calendar-top"><strong>${new Date(dates[0]+'T12:00:00').toLocaleDateString('ko-KR',{year:'numeric',month:'long'})}</strong><div class="calendar-controls"><button class="text-button" data-action="week-today">이번 주</button><button class="icon-button" data-action="week-prev" aria-label="이전 주">${icon('back')}</button><button class="icon-button" data-action="week-next" aria-label="다음 주">${icon('arrow')}</button></div></div><div class="week-grid">${dates.map((date,i)=>`<button class="day-cell ${date===selectedDate?'selected':''} ${date===today()?'today':''}" data-date="${date}"><span class="day-label">${['월','화','수','목','금','토','일'][i]}</span><span class="day-num">${Number(date.slice(-2))}</span><span class="day-pomo pomo-count">${state.tasks.filter(t=>t.date===date).reduce((s,t)=>s+t.estimate,0)}${tomato(true)}</span></button>`).join('')}</div><div class="section-heading"><h2>${dateLabel(selectedDate)}</h2><span>날짜로 드래그하여 이동</span></div>${list(state.tasks.filter(t=>t.date===selectedDate))}${addButton('할 일 추가')}`;
 }else{html=`<section class="settings-card"><h2>포모도로 설정</h2><p>변경한 시간은 다음 포모도로부터 적용됩니다.</p><div class="setting-row"><span>집중 시간</span><select id="focus-setting" aria-label="집중 시간">${[[900,'15분'],[1500,'25분'],[3000,'50분'],[10,'10초 · 데모 체험']].map(([v,n])=>`<option value="${v}" ${state.settings.focus===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="setting-row"><span>휴식 시간</span><select id="rest-setting" aria-label="휴식 시간">${[[300,'5분'],[600,'10분'],[5,'5초 · 데모 체험']].map(([v,n])=>`<option value="${v}" ${state.settings.rest===v?'selected':''}>${n}</option>`).join('')}</select></div></section><section class="settings-card"><h2>최근 집중 기록</h2><p>작업 전환 시 0 / 0.5 / 1포모도로로 반올림합니다.</p>${state.records.length?state.records.slice(-5).reverse().map(r=>`<div class="record-row"><div class="record-title">${escape(state.tasks.find(t=>t.id===r.taskId)?.title||'삭제된 할 일')}<br><small>실제 ${Math.floor(r.seconds/60)}분 ${Math.floor(r.seconds%60)}초</small></div><span class="record-value pomo-count">${r.pomodoros}${tomato(true)}</span></div>`).join(''):'<p>집중 기록이 없습니다.</p>'}</section><section class="settings-card"><h2>로컬 데이터</h2><p>할 일과 집중 기록은 이 브라우저에 저장됩니다.</p><button class="secondary" data-action="export">데이터 내보내기</button></section>`;}
 $('#workspace-content').innerHTML=html;
}
function renderExecution(){const timer=state.timer;const task=state.tasks.find(t=>t.id===timer?.taskId);const rest=timer?.phase==='rest';const todays=state.tasks.filter(t=>t.date===today());const pending=todays.filter(t=>!t.done);$('#focus-title').textContent=rest?'휴식':task?.title||'';$('#focus-title').style.display=rest||task?'block':'none';$('#timer-status').textContent=timer?(rest?(timer.running?'휴식 중':'휴식 대기'):timer.running?'집중 중':'일시정지'):'';$('.execution-heading').style.display=timer?'flex':'none';$('#timer-status').classList.toggle('running',!!timer?.running&&!rest);$('.timer-panel').classList.toggle('running-pulse',!!timer?.running);const startLabel=timer?(timer.running?'일시정지':rest?'휴식 시작':'집중 재개'):'집중 시작';$('#main-action').innerHTML=icon(timer?.running?'pause':'play')+startLabel;$('#main-action').disabled=!timer&&!pending.length;$('#end-action').innerHTML=icon(rest?'arrow':'stop');$('#end-action').disabled=!timer;$('#end-action').setAttribute('aria-label',rest?'휴식 종료':'집중 종료');
 $('#today-count').textContent=pending.length;$('#today-estimate').innerHTML=`예상 <span class="pomo-count">${todays.reduce((s,t)=>s+t.estimate,0)}${tomato(true)}</span>`;
 $('#today-list').innerHTML=todays.length?todays.map((t,i)=>{const active=timer?.phase==='focus'&&timer.taskId===t.id;return `<div class="today-row ${active?'active':''} ${t.done?'done':''}"><span class="today-number">${t.done?icon('check'):String(i+1).padStart(2,'0')}</span><div class="today-info"><div class="today-name ${t.done?'task-title':''}">${escape(t.title)}</div>${pomos(t.estimate,taskTotal(t.id))}</div><button class="play-button" data-action="play" data-id="${t.id}" aria-label="${escape(t.title)} ${active&&timer.running?'일시정지':'시작'}" ${t.done?'disabled':''}>${icon(active&&timer.running?'pause':'play')}</button></div>`}).join(''):'<div class="empty">오늘 예정된 할 일이 없습니다.</div>';
 const total=state.records.filter(r=>localDate(new Date(r.at))===today()).reduce((s,r)=>s+r.pomodoros,0);$('#daily-total').innerHTML=`${total} <small>포모도로</small>`;$('#daily-dots').innerHTML=Array.from({length:Math.max(3,Math.min(8,Math.ceil(total)))},(_,i)=>tomato(i<total)).join('');updateClock();}
function updateClock(){const t=state.timer;const elapsed=t?elapsedSeconds(t):0;const seconds=Math.max(0,Math.ceil((t?.duration||state.settings.focus)-elapsed));const clockText=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(updateClock.last!==clockText){updateClock.last=clockText;$('#clock').innerHTML=[...clockText].map(c=>`<span class="${c===':'?'colon':'digit'}">${c}</span>`).join('');}$('#timer-progress').style.width=t?`${elapsed/t.duration*100}%`:'0%';document.title=t?.running?`${$('#clock').textContent} · ${t.phase==='rest'?'휴식':'집중'} — To3mato`:'To3mato';}
function render(){renderWorkspace();renderExecution();}
function pause(){const t=state.timer;if(!t)return;if(t.running){t.elapsed=elapsedSeconds(t);t.running=false;}else{t.startedAt=Date.now();t.running=true;}save();renderExecution();}
function play(id){const task=state.tasks.find(t=>t.id===id);if(!task||task.done)return;if(state.timer?.taskId===id&&state.timer?.phase==='focus'&&state.timer.running){pause();return;}const record=startTask(state,id,state.settings.focus);save();render();if(record)notify(`${record.pomodoros}포모도로 기록 · 새 타이머 시작`);}
function end(){const rest=state.timer?.phase==='rest';const record=settleTimer(state);save();render();notify(rest?'휴식 종료':`${record?.pomodoros||0}포모도로 기록 완료`);}
function complete(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;if(!t.done&&state.timer?.taskId===id)settleTimer(state);t.done=!t.done;save();render();notify(t.done?'할 일을 완료했습니다.':'완료를 취소했습니다.');}
function openTask(id=null,assignedDate=undefined){editId=id;const t=state.tasks.find(t=>t.id===id);$('#dialog-title').textContent=t?'할 일 수정':'할 일 추가';$('#task-title').value=t?.title||'';$('#task-estimate').value=t?.estimate||1;$('#task-date').value=t?t.date:assignedDate!==undefined?assignedDate:tab==='calendar'?selectedDate:today();$('#task-project').innerHTML='<option value="">프로젝트 없음</option>'+state.projects.map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('');$('#task-project').value=t?.project||projectView||'';$('#delete-task').hidden=!t;$('#task-dialog').showModal();$('#task-title').focus();}
$('#task-form').addEventListener('submit',e=>{e.preventDefault();const title=$('#task-title').value.trim();if(!title){$('#task-title').setCustomValidity('할 일 이름을 입력하세요.');$('#task-title').reportValidity();return;}const data={title,estimate:Number($('#task-estimate').value),date:$('#task-date').value,project:$('#task-project').value};if(editId)Object.assign(state.tasks.find(t=>t.id===editId),data);else state.tasks.push({id:uid(),done:false,...data});save();$('#task-dialog').close();render();notify(editId?'할 일을 수정했습니다.':'할 일을 추가했습니다.');});
$('#task-title').addEventListener('input',()=>$('#task-title').setCustomValidity(''));
$('#close-dialog').addEventListener('click',()=>$('#task-dialog').close());
$('#delete-task').addEventListener('click',()=>{if(state.timer?.taskId===editId)settleTimer(state);state.tasks=state.tasks.filter(t=>t.id!==editId);save();$('#task-dialog').close();render();notify('할 일을 삭제했습니다. 집중 기록은 유지됩니다.');});
$('#main-action').addEventListener('click',()=>state.timer?pause():play(state.tasks.find(t=>t.date===today()&&!t.done)?.id));$('#end-action').addEventListener('click',end);
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.tab){tab=button.dataset.tab;projectView=null;renderWorkspace();return;}if(button.dataset.project){projectView=button.dataset.project;renderWorkspace();return;}if(button.dataset.date){selectedDate=button.dataset.date;renderWorkspace();return;}const action=button.dataset.action,id=button.dataset.id;if(action==='add')openTask(null,button.dataset.addDate);if(action==='edit')openTask(id);if(action==='complete')complete(id);if(action==='play')play(id);if(action==='project-back'){projectView=null;renderWorkspace();}if(action==='add-project'){const name=prompt('프로젝트 이름');if(name?.trim()){state.projects.push({id:uid(),name:name.trim().slice(0,80),icon:'folder',color:'#84956c'});save();renderWorkspace();}}if(action==='week-prev'||action==='week-next'){weekOffset+=action==='week-next'?1:-1;renderWorkspace();}if(action==='week-today'){weekOffset=0;selectedDate=today();renderWorkspace();}if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`to3mato-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('할 일과 집중 기록을 내보냈습니다.');}});
document.addEventListener('change',e=>{if(e.target.id==='focus-setting'||e.target.id==='rest-setting'){state.settings[e.target.id==='focus-setting'?'focus':'rest']=Number(e.target.value);save();renderExecution();notify('다음 포모도로부터 적용됩니다.');}});
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-task]');if(row)e.dataTransfer.setData('text/plain',row.dataset.task);});document.addEventListener('dragover',e=>{const day=e.target.closest('[data-date]');if(day){e.preventDefault();day.classList.add('drag-over');}});document.addEventListener('dragleave',e=>e.target.closest('[data-date]')?.classList.remove('drag-over'));document.addEventListener('drop',e=>{const day=e.target.closest('[data-date]');if(!day)return;e.preventDefault();const t=state.tasks.find(t=>t.id===e.dataTransfer.getData('text/plain'));if(t){t.date=day.dataset.date;save();render();notify('예정일을 변경했습니다.');}});
function tick(){const t=state.timer;if(t?.running&&elapsedSeconds(t)>=t.duration){const phase=t.phase;settleTimer(state);if(phase==='focus')state.timer={phase:'rest',taskId:null,duration:state.settings.rest,elapsed:0,startedAt:Date.now(),running:false};save();render();notify(phase==='focus'?'1포모도로 완료. 휴식을 시작할 수 있습니다.':'휴식 완료');}else updateClock();}
window.addEventListener('pagehide',save);render();tick();setInterval(tick,250);
